$baseline=$l->getSummary($f);$nodes=$l->getNodesList($f);check(count(array_filter($nodes,fn($r)=>$r['object_node_id']==10))===1,'one node despite duplicated joins');check(count(array_values(array_filter($nodes,fn($r)=>$r['object_node_id']==10))[0]['map_references'])===2,'all references retained');
$rows=[];foreach(array_merge($l->getLessonsList($f),$nodes)as$r)$rows[ResearchCuration::key($r)]=$r;
$candidates=ResearchCuration::candidates(array_values($rows));check(count(array_filter($candidates,fn($c)=>in_array('map/reflection/dup-a',$c['keys'])))===1,'lesson exact candidate');
$other=$rows['map/reflection/dup-a'];$other['user_id']=2;$other['reflection_group_id']='other';$c=ResearchCuration::candidates([$rows['map/reflection/dup-a'],$other]);check(!$c,'no cross participant candidate');
check(ResearchCuration::normalize("　 A\r\nB \t")==="A\nB",'normalization');check(ResearchCuration::normalize('A B')!==ResearchCuration::normalize('AB'),'internal spaces retained');
$path=sys_get_temp_dir().'/curation-'.bin2hex(random_bytes(8)).'.sqlite';$store=new ResearchCuration($path);
try{
 $base=$store->read();$in=['mode'=>'exclude','keys'=>['map/reflection/dup-a','map/reflection/dup-b'],'representative'=>'map/reflection/dup-a','reason'=>'synthetic duplicate'];
 $next=ResearchCuration::propose($base,$rows,$in,'test');$preview=$store->preview('test',['next'=>$next]);check($store->previewData('test',$preview)['next']==$next,'preview roundtrip');
 try{$store->previewData('other',$preview);throw new Exception('actor leak');}catch(RuntimeException $e){check($e->getCode()===409,'preview actor scoped');}
 $saved=$store->commit('test',0,$next,'operation-00000001','fingerprint');check($saved['revision']===1,'revision');check($store->commit('test',0,$next,'operation-00000001','fingerprint')===$saved,'idempotent retry');
 try{$store->commit('test',0,$next,'operation-00000002','other');throw new Exception('stale accepted');}catch(RuntimeException $e){check($e->getCode()===409,'CAS');}
 try{$store->result('operation-00000001','wrong');throw new Exception('UUID reused');}catch(RuntimeException $e){check($e->getCode()===409,'fingerprint checked');}
 $l->setCuration($saved);$summary=$l->getSummary($f);check($summary['lessons_total']===$baseline['lessons_total']-1,'lesson total decreased');check($summary['lessons_updated']===$baseline['lessons_updated'],'update flag not merged or inflated');check(count($l->getLessonsList($f))===$summary['lessons_total'],'list summary agree');check($l->getAggregationData($f,'lessons_total','month','user')['grand_total']===$summary['lessons_total'],'aggregation and evidence agree');check($summary['statistics']['lessons_total']['mean']===$summary['lessons_total']/2,'zeros remain in denominator');
 $nodeIn=['mode'=>'exclude','keys'=>['means/10','means/11'],'representative'=>'means/10','reason'=>'same means duplicate'];$nodeNext=ResearchCuration::propose($saved,$rows,$nodeIn,'test');$nodeSaved=$store->commit('test',1,$nodeNext,'operation-00000003','nodes');$l->setCuration($nodeSaved);$s=$l->getSummary($f);check($s['nodes_total']===$baseline['nodes_total']-1,'means count curated');check($s['nodes_completed']===$baseline['nodes_completed']-1,'completed curated');check($s['nodes_with_reason']===$baseline['nodes_with_reason']-1,'reasons curated');check($l->getAggregationData($f,'nodes_total','month','user')['grand_total']===$s['nodes_total'],'means evidence agrees');
 $l->setCuration(array_merge($nodeSaved,['include_excluded'=>true]));check($l->getSummary($f)['lessons_total']===$baseline['lessons_total'],'raw totals restored');check(count(array_filter($l->getLessonsList($f),fn($r)=>$r['curation_state']==='excluded'))===1,'raw view keeps exclusion annotations');
 $undo=ResearchCuration::propose($nodeSaved,$rows,['mode'=>'undo','group_id'=>array_key_first($nodeSaved['groups']),'reason'=>'undo synthetic'],'test');$restored=$store->commit('test',2,$undo,'operation-00000004','undo');$l->setCuration($restored);check($l->getSummary($f)['lessons_total']===$baseline['lessons_total'],'undo restores count');check(count(ResearchCuration::exclusions($store->read(1)))===1,'old revision immutable');check($store->read(0)['revision']===0,'revision zero reproducible');
 $hash=ResearchCuration::hash($rows['map/reflection/dup-a']);$changed=$rows['map/reflection/dup-a'];$changed['why_important']='changed';check(ResearchCuration::hash($changed)!==$hash,'source changes detected');
 $distinct=ResearchCuration::propose($restored,$rows,array_merge($in,['mode'=>'distinct']),'test');check(ResearchCuration::exclusions($distinct)===ResearchCuration::exclusions($restored),'distinct judgment never changes counts');
 echo "PASS: curation candidates, zero population, summary/list/evidence agreement, references, immutable revisions, undo, actor isolation, CAS, idempotency, raw mode, source hashes.\n";
}finally{unset($store);unlink($path);}
